        {
            "@type": "FAQPage",
            "@id": "https://domozmsk.ru/uslugi/newyear#faq",
            "mainEntity": [
                {
                    "@type": "Question",
                    "name": "Когда лучше заказывать новогоднее оформление?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Рекомендуем обращаться за 1–2 месяца до начала праздничного сезона. Это позволяет заранее разработать концепцию, подобрать материалы и запланировать удобные сроки монтажа."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Какие объекты вы оформляете?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Мы выполняем новогоднее оформление частных домов, коттеджных поселков, жилых комплексов, ресторанов, отелей, офисных зданий, торговых объектов и общественных пространств."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Что входит в услугу?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Комплекс работ может включать разработку концепции, оформление фасадов и входных групп, архитектурную подсветку зданий, украшение деревьев и территории, монтаж световых конструкций, подключение оборудования и последующий демонтаж."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Можно ли оформить только фасад здания?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Да. Мы выполняем как комплексное новогоднее оформление объекта, так и отдельные виды работ: подсветку фасада, оформление входной группы, украшение деревьев или установку световых композиций."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Разрабатываете ли вы индивидуальный дизайн?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Да. Каждый проект создается с учетом архитектуры объекта, окружающего пространства и пожеланий заказчика. Мы стремимся к тому, чтобы праздничное оформление выглядело гармонично и подчеркивало особенности территории."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Безопасно ли световое оборудование?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Мы используем профессиональное оборудование и материалы, предназначенные для эксплуатации на улице в зимний период. Все элементы проходят проверку перед монтажом."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Выполняете ли вы монтаж и демонтаж?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Да. Наша команда берет на себя полный цикл работ — от установки и подключения оборудования до демонтажа после завершения праздничного сезона."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Работаете ли вы с коммерческими объектами?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Да. Мы реализуем проекты для ресторанов, гостиниц, бизнес-центров, торговых комплексов, жилых кварталов и других общественных пространств."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Сколько стоит новогоднее оформление?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Стоимость зависит от площади объекта, выбранной концепции, объема декоративных элементов и сложности монтажа. После консультации мы подготовим индивидуальное коммерческое предложение."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Можно ли использовать существующую подсветку или декор?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Да. При необходимости мы можем интегрировать уже имеющиеся элементы в новый проект оформления или дополнить существующую систему освещения."
                    }
                },
                {
                    "@type": "Question",
                    "name": "За какое время выполняется монтаж?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Сроки зависят от масштаба проекта и объема работ. Оформление входной группы или фасада частного дома обычно занимает от 1 до 3 дней. Комплексное новогоднее оформление территории, жилого комплекса или коммерческого объекта может потребовать больше времени. Точные сроки определяются после осмотра объекта и согласования концепции."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Когда начинается монтаж новогоднего оформления?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Большинство проектов реализуется с ноября по середину декабря. Раннее бронирование позволяет выбрать удобные даты монтажа и подготовить объект к праздничному сезону без спешки."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Выполняете ли вы демонтаж после праздников?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Да. После завершения новогоднего сезона мы аккуратно демонтируем все элементы оформления, проверяем оборудование и приводим территорию в первоначальное состояние."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Что происходит с декором после демонтажа?",
